<?php $title='Manage services'; $subtitle='Thoughtful care, with pricing you control.'; $edit=isset($_GET['edit'])?one('SELECT * FROM services WHERE id=?',[(int)$_GET['edit']]):null; require __DIR__.'/header.php'; ?>
<div class="booking-layout"><section class="panel"><h2>Service catalogue</h2><p class="muted">Removing a service hides it from new bookings. Existing orders retain their original prices.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Service</th><th>Price / item</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php foreach(query('SELECT * FROM services ORDER BY id')->fetchAll() as $s): ?><tr><td><strong><?= e($s['service_name']) ?></strong><small><?= e($s['description']) ?></small></td><td><?= money($s['price']) ?></td><td><?= badge($s['is_active']?'Active':'Inactive') ?></td><td><div class="table-actions"><a class="btn btn-sm btn-light" href="?edit=<?= $s['id'] ?>">Edit</a><?php if($s['is_active']): ?><form method="post" action="<?= e(url('actions/handle.php')) ?>" data-confirm="Remove this service from the catalogue?"><?= csrf() ?><input type="hidden" name="action" value="service_delete"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form><?php endif ?></div></td></tr><?php endforeach ?></tbody></table></div></section><aside class="panel"><h2><?= $edit?'Edit service':'Add a service' ?></h2><form method="post" action="<?= e(url('actions/handle.php')) ?>"><?= csrf() ?><input type="hidden" name="action" value="service_save"><input type="hidden" name="id" value="<?= $edit['id']??0 ?>"><label>Service name<input class="form-control" name="service_name" maxlength="100" value="<?= e($edit['service_name']??'') ?>" required></label><label>Description<textarea class="form-control" name="description" maxlength="500" required><?= e($edit['description']??'') ?></textarea></label><label>Price per item (LKR)<input class="form-control" type="number" name="price" step="0.01" min="0.01" max="999999.99" value="<?= e($edit['price']??'') ?>" required></label><label class="check-label"><input name="is_active" type="checkbox" <?= !$edit || $edit['is_active']?'checked':'' ?>> Available for booking</label><button class="btn btn-primary w-100">Save service</button><?php if($edit): ?><a class="btn btn-light w-100 mt-2" href="<?= e(url('admin/services.php')) ?>">Cancel editing</a><?php endif ?></form></aside></div>
